update content_bodies set title = '森の京都【秋冬】Woodland Kyoto -Deep into the heart of authentic Japan-', description = '嵐山を流れる水は、どこからくるのでしょうか。
鹿苑寺金閣が借景とする森は、どこまで続いているのでしょうか。
そこは、いまだ知られざるもうひとつの古都、「森の京都」。

山から湧き出す清らかな水と肥えた大地は、京都を支え、人々の暮らしと地域文化を育んできました。
素朴な里山の風景のなかに、受け継がれた知恵を活かし峻厳な森や河と共存して生きる人々がいます。

秋冬の彩り豊かな景色と、自然とともに暮らす人々の美しさをぜひご覧ください。
歴史と伝統の京都から、自然と生命がいきづく「森の京都」へとつながる旅の始まりです。

