update content_bodies set title = 'Woodland Kyoto -Deep into the heart of authentic Japan-', description = 'Where does the water flowing through Arashiyama come from?
How far does the forest, which is the borrowed scenery of Kinkaku-ji, extend?
It is another ancient capital, still unknown, "Woodland Kyoto."

The pure water that springs from the mountains and the fertile land have supported Kyoto, nurturing the lives of its people and local culture.
Amidst the rustic landscape of satoyama, there are people who live in harmony with the majestic forests and rivers, utilizing the wisdom passed down through generations.

Please enjoy the vibrant autumn and winter scenery, and the beauty of the people living in harmony with nature.
This is the beginning of a journey that connects the historical and traditional Kyoto to the "Woodland Kyoto" where nature and life thrive.

#CJ動画2021
------------------------------------------------
