update content_bodies set title = 'さっぽろテレビ塔 4K／北海道の絶景景色 【BESTHOKKAIDO_VOL.85】Superb view of Hokkaido/Sapporo TV Tower', description = '北海道の魅力な観光スポットや観光資源を紹介するBEST HOKKAIDO。
北海道の絶景景色を様々な角度から映像でお届けします。

#ベスト北海道 #北海道観光 #さっぽろ夜景プロジェクト

全国の様々な夜景都市を制して「日本新三大夜景」に認定された札幌の夜景。今回は、さっぽろテレビ塔からの夜景をご紹介。

1957年（昭和32年）に完成し、同年8月24日に開業したさっぽろテレビ塔。札幌の中心部を南北に分ける大通公園に札幌のランドマーク的存在としてそびえ立つ観光施設。地上約90mの展望台からは、季節ごとに表情を変える公園の美しい風景やイベントの様子が楽しめる。
ホワイトイルミネーションや雪まつりが開催される冬は、特等席的な場所。

詳しくはこちらから！
https://www.tv-tower.co.jp/

2022年3月19 日（土） ? 27 日（日）から、
「PLANET FLOWERS SAPPORO」と題して植物と光の幻想空間を演出した夜景が見れるイベントがさっぽろテレビ塔で開催。
いつもよりさらに美しい札幌の夜景を楽しめます。
その他、もいわ山（3月19日～21日実施）や、大倉山（3月26日・27日実施）でも開催します。
詳しくはこちらから！
https://sapporoyakei.jp/#about

