The night view of Sapporo, which has been certified as one of the "New Three Major Night Views of Japan" by controlling various night view cities nationwide.
This time, we will introduce the night view from the Sapporo TV Tower.

The Sapporo TV Tower was completed in 1957 and opened on August 24 of the same year.
A tourist facility that rises as a landmark of Sapporo in Odori Park, which divides the center of Sapporo into north and south.
From the observatory, which is about 90 meters above the ground, you can enjoy the beautiful scenery of the park and the events that change with the seasons.
In winter, when the White Illumination and the Snow Festival are held, it is a place with special seats.

For more information is here!
https://www.tv-tower.co.jp/


From Saturday, March 19th to Sunday, March 27th, 2022
An event entitled "PLANET FLOWERS SAPPORO" will be held at Sapporo TV Tower where you can see the night view that creates an illusionary space of plants and light.
You can enjoy the more beautiful night view of Sapporo than usual.
In addition, it will be held at Mt. Moiwa (held from March 19th to 21st) and Mt. Okura (held on March 26th and 27th).
For more information is here!
https://sapporoyakei.jp/#about

In addition, post a night view photo of Sapporo on SNS with a hashtag.
