update content_bodies set title = 'Ichinose-yaki in Ukiha City, Fukuoka Prefecture', description = 'This is an introduction video about Ichinose-yaki in Ukiha City, Fukuoka Prefecture.

Ichinose-yaki is said to have originated when Toyotomi Hideyoshi invited potters during the Korean draft. It reached its peak around 1840 and became the official kiln of the Arima Domain. Although it was later abandoned, it developed again due to the enthusiasm for reviving the local kiln, and now there are five kilns.' where id = 'cvBGBANwnxz5qbgm3Zxm7';
update content_bodies set title = '【うきはの職人】行徳製菓＃1', description = 'うきはの職人をご紹介！
