update content_bodies set title = '【福岡県うきは市】一の瀬焼き', description = '福岡県うきは市の一の瀬焼きのご紹介動画です。

一の瀬焼きは、豊臣秀吉が朝鮮徴兵の時に陶工を招いたことが起こりと言われています。1840年頃最盛期を迎え、有馬藩の御用窯となった後廃窯となったものの、郷土の窯を再びという熱意によって発展し現在5つの窯元がある。

□■令和５年５月３日〜７日■□
一の瀬焼　春の陶器まつり開催！

５軒の窯元がそろって春の窯開き。見学や販売を行います。

#うきは市 #うきは #福岡県 #観光 #一の瀬焼き#fukuoka #ukiha' where id = 'UWI1lJeRYA3H4K1gUnuVf';
update content_bodies set title = '[Ukiha City, Fukuoka Prefecture] Ichinose-yaki', description = 'This is an introduction video about Ichinose-yaki in Ukiha City, Fukuoka Prefecture.

Ichinose-yaki is said to have originated when Toyotomi Hideyoshi invited potters during the Korean draft. It reached its peak around 1840 and became the official kiln of the Arima Domain, but after being abandoned, it developed again due to the enthusiasm for reviving the local kiln, and now there are five kilns.

□■ May 3rd to May 7th, 2023 ■□
Ichinose-yaki Spring Pottery Festival is being held!

All five kilns will open for the spring kiln opening. Tours and sales will be conducted.

#UkihaCity #Ukiha #FukuokaPrefecture #Tourism #IchinoseYaki #fukuoka #ukiha' where id = 'UKY6NqZXWLHaT5-DYnMaX';
update content_bodies set title = '【福岡県うきは市】道の駅うきはからパールワイン登場！', description = '令和５年3月25日、道の駅うきはでぶどうのパールワインが新発売！
うきは市でとれたぶどうのうち、傷などで出荷できないものを使って作られたものです。

この日、プロジェクトメンバーで試飲会を行いました。
果実の澱が入っており香りも良く、とてもおいしい出来となり、今後もいろんなフルーツで商品化できるのではないかと期待が高まりました。
うきはの実りが余すことなく皆さんに届きますように。

