update content_bodies set title = '[Ukiha City, Fukuoka Prefecture] Pearl Wine Debuts at Roadside Station Ukiha!', description = 'On March 25, 2023, pearl wine made from grapes was newly released at Roadside Station Ukiha!
It is made from grapes harvested in Ukiha City that could not be shipped due to damage or other issues.

On this day, a tasting event was held with project members.
The wine contains fruit sediment, has a pleasant aroma, and turned out to be very delicious, raising expectations that various fruits could be commercialized in the future.
May the bounty of Ukiha reach everyone without waste.

