update content_bodies set title = '【2025年】雫石よしゃれ祭【新生雫石町70周年記念】', description = '【よしゃれ祭とは？】毎年8月11日に開催される夏の雫石町の一大イベント。よしゃれ通り商店街をメイン会場に、神輿運行、よしゃれ踊りやさんさ踊りなど、各団体によって異なる彩り豊かなパレードが催され、最後はさんさとよしゃれの輪踊りで締め括られます。メイン会場の他、よさこい演舞、雫石郷土芸能競演、南部よしゃれ全国大会最優秀賞者競演なども開催されます。
8月11日は、「よしゃれの里 雫石町」へぜひお越しください！

　天正年間（１５７３〜９２）、南部信直が雫石城攻略の際に西山村（雫石町）の「五輪茶屋」（よしゃれ茶屋）で見せた「雫石女」の貞節と心意気を唄ったものといわれ、「南部牛追唄」と並ぶ岩手の代表的民謡の一つ。踊りが完成したのは藩政末期といわれるが、昭和の始めごろに現在の形に手直しされ、現在でも祝い事の宴席や舞台などでは紋付で踊られる格調高い民謡である。
（いわての文化情報大事典ホームページより引用）
http://www.bunka.pref.iwate.jp/archive/folk15

雫石町ホームページ
https://www.town.shizukuishi.iwate.jp/
しずくいし観光協会ホームページ
https://shizukuishi-kanko.gr.jp/index.html


