#よしゃれ踊り #さんさ踊り #雫石さんさ
#岩手 #伝統芸能 #郷土芸能' where id = 'OEqLSgglEbki7McND67uk';
update content_bodies set title = '[2025] Shizukuishi Yosharai Festival [70th Anniversary of the New Shizukuishi Town]', description = '[What is the Yosharai Festival?] A major summer event in Shizukuishi Town held every year on August 11. The main venue is the Yosharai Street shopping district, where various groups hold colorful parades featuring mikoshi (portable shrines), Yosharai dances, and Sansha dances, culminating in a circle dance of Sansha and Yosharai. In addition to the main venue, there are also performances of Yosakoi dance, Shizukuishi traditional performing arts competition, and a showcase of the winners of the Nanbu Yosharai National Competition.
Please come to ''Yosharai no Sato Shizukuishi Town'' on August 11!

It is said that during the Tensho era (1573-1592), when Nanbu Nobunao attacked Shizukuishi Castle, he sang about the chastity and spirit of the ''Shizukuishi Woman'' at the ''Gorin Chaya'' (Yosharai Chaya) in Nishiyama Village (Shizukuishi Town). This song is one of Iwate''s representative folk songs, alongside the ''Nanbu Ushio Uta.'' The dance is said to have been completed at the end of the feudal era, but it was revised into its current form around the early Showa period and is still performed in formal attire at celebratory events and on stage as a dignified folk song.
(Quoted from the Iwate Cultural Information Encyclopedia website)
http://www.bunka.pref.iwate.jp/archive/folk15

