*Precautions
The information introduced in the video may change. Please check the official website for details before visiting the site.

*Selection Criteria
The selection and introduction criteria for the spots introduced in the video depend on values and preferences, but we will strive to incorporate as many opinions and feedback as possible to improve.

*Copyright (Regarding Images)
This channel is produced based on [official websites and various media information], but regarding images, we quote them without altering the photos and have referenced them in the video under the advice of a lawyer to avoid reproducing or adapting copyrighted works. Of course, we are committed to ensuring that we do not inconvenience the image authors and to delivering valuable travel information to our viewers. However, if any copyright holders wish to request the removal of images in a way that causes them any disadvantage, we would appreciate it if you could contact us at the address below. We will respond promptly.

Contact Information
